BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SELECT plan(16);
INSERT INTO auth.users(id,email) VALUES('ffffffff-0000-0000-0000-000000000001','passagea@test.local'),('ffffffff-0000-0000-0000-000000000002','passageb@test.local');
INSERT INTO public.works(id,user_id,work_type,title) VALUES('ffffffff-1000-0000-0000-000000000001','ffffffff-0000-0000-0000-000000000001','book','Indexed book');
INSERT INTO public.records(id,work_id,record_type) VALUES('ffffffff-2000-0000-0000-000000000001','ffffffff-1000-0000-0000-000000000001','edition');
INSERT INTO public.assets(id,user_id,bucket,storage_path,file_size,checksum_sha256,mime_type,file_format) VALUES('ffffffff-3000-0000-0000-000000000001','ffffffff-0000-0000-0000-000000000001','documents','passage-fixture.pdf',100,'passage-test','application/pdf','pdf');
INSERT INTO public.record_assets(record_id,asset_id) VALUES('ffffffff-2000-0000-0000-000000000001','ffffffff-3000-0000-0000-000000000001');
SELECT public.queue_passage_index('ffffffff-3000-0000-0000-000000000001','ffffffff-0000-0000-0000-000000000001');
CREATE TEMP TABLE testjob AS SELECT id FROM public.jobs WHERE user_id='ffffffff-0000-0000-0000-000000000001';
UPDATE public.jobs SET status='running',claim_generation=1,lease_expires_at=now()+interval '1 minute' WHERE id=(SELECT id FROM testjob);
SELECT is(public.commit_passage_batch((SELECT id FROM testjob),0,'[{"ordinal":0,"page":9,"content":"Photovoltaic panels güneş enerjisi"}]',9,10),false,'stale claim cannot write passages');
SELECT is(public.commit_passage_batch((SELECT id FROM testjob),1,'[{"ordinal":0,"page":9,"content":"Photovoltaic panels güneş enerjisi"}]',9,10),true,'checkpoint commits atomically');
SELECT is((SELECT (payload->>'from')::int FROM public.jobs WHERE id=(SELECT id FROM testjob)),9,'resume cursor advanced');
SELECT is((SELECT status FROM public.jobs WHERE id=(SELECT id FROM testjob)),'queued','continuation queued');
SELECT public.merge_extraction_metadata('ffffffff-3000-0000-0000-000000000001','ffffffff-0000-0000-0000-000000000001','{"filename":"book.pdf"}');
SELECT is((SELECT (metadata->'passage_index'->>'done')::int FROM public.assets WHERE id='ffffffff-3000-0000-0000-000000000001'),9,'extraction preserves the newer checkpoint');
SELECT is(public.queue_passage_index('ffffffff-3000-0000-0000-000000000001','ffffffff-0000-0000-0000-000000000001'),false,'automatic queue replay cannot restart indexing');
SELECT throws_ok($$INSERT INTO public.asset_passages(asset_id,user_id,index_version,ordinal,content) VALUES('ffffffff-3000-0000-0000-000000000001','ffffffff-0000-0000-0000-000000000002','bad',0,'secret')$$,'23503',NULL,'composite foreign key prevents wrong owner');
SET LOCAL ROLE authenticated;
SET LOCAL request.jwt.claims='{"sub":"ffffffff-0000-0000-0000-000000000002","role":"authenticated"}';
SELECT throws_ok($$INSERT INTO public.asset_passages(asset_id,user_id,index_version,ordinal,content) VALUES('ffffffff-3000-0000-0000-000000000001','ffffffff-0000-0000-0000-000000000002','bad',1,'secret')$$,'42501',NULL,'authenticated user cannot write passage rows');
SELECT is_empty('SELECT id FROM public.asset_passages','second user cannot read text');
SELECT is_empty($$SELECT id FROM public.search_passages('Photovoltaic')$$,'second user cannot retrieve sources');
SELECT is(public.control_passage_index('cancel','ffffffff-3000-0000-0000-000000000001'),0,'second user cannot cancel indexing');
SET LOCAL request.jwt.claims='{"sub":"ffffffff-0000-0000-0000-000000000001","role":"authenticated"}';
SELECT is((SELECT page FROM public.search_passages('Photovoltaic')),9,'text beyond old eight-page cutoff is searchable');
SELECT is((SELECT count(*)::int FROM public.search_passages('güneş')),1,'non-English FTS retains words');
SELECT is_empty($$SELECT id FROM public.search_passages('Photovoltaic',20,ARRAY['ffffffff-1000-0000-0000-000000000002'::uuid])$$,'work filter applied inside retrieval');
SELECT is(public.control_passage_index('cancel','ffffffff-3000-0000-0000-000000000001'),1,'owner cancels live continuation');
RESET ROLE;
SELECT is(public.commit_passage_batch((SELECT id FROM testjob),1,'[]',10,10,'complete'),false,'cancelled worker cannot finish');
SELECT * FROM finish();
ROLLBACK;
